1	package posemap
2	
3	import (
4		"math"
5		"sort"
6	)
7	
8	// poseShift 描述一次回环校正对轨迹施加的同一次刚体重定位：锚点落到目标
9	// 位置、朝向归一到 [-π,π)；从锚点到末帧的其余帧与锚点一起平移旋转，保留
10	// 各帧相对锚点的位置关系与朝向差。提交校正（Correct）与打开地图时的校正
11	// 记录几何核对（validateLoaded，见 persistence.go）共用这同一份规则与
12	// 运算次序，两处对“校正后位置与朝向”的理解因此始终一致。
13	type poseShift struct {
14		x, y          float64 // 目标位置，即锚点校正后位置
15		heading       float64 // 目标朝向归一到 [-π,π)，即锚点校正后朝向
16		anchorX       float64 // 锚点校正前位置
17		anchorY       float64
18		anchorHeading float64 // 锚点校正前朝向
19		dHeading      float64 // 归一后的最短朝向差，即各帧叠加的旋转角
20		cosD, sinD    float64 // 旋转角的余弦与正弦
21		identity      bool    // 只调方差的恒等校正：位置与朝向保持原值
22	}
23	
24	// newPoseShift 按提交目标与锚点校正前位姿构造重定位。目标朝向先归一，
25	// 旋转角取归一后的最短朝向差。目标位置与锚点原位置完全相同、目标朝向归
26	// 一后与原朝向等价（旋转角为 0）时是恒等校正：几何上没有任何平移或旋
27	// 转，校正前后位姿必须完全相同。恒等校正不能套用旋转平移公式——公式会
28	// 先求相对锚点的偏移，轨迹横跨 ±1e308 这类大坐标时该差值先溢出为
29	// ±Inf、再参与浮点运算退化为 NaN，使本应成功的校正被误判为数值异常；
30	// 恒等校正直接保留原位姿。
31	func newPoseShift(tgt CorrectionTarget, anchorBefore Pose) poseShift {
32		heading := normalizeAngle(tgt.Heading)
33		dHeading := normalizeAngle(heading - anchorBefore.Heading)
34		return poseShift{
35			x:             tgt.X,
36			y:             tgt.Y,
37			heading:       heading,
38			anchorX:       anchorBefore.X,
39			anchorY:       anchorBefore.Y,
40			anchorHeading: anchorBefore.Heading,
41			dHeading:      dHeading,
42			cosD:          math.Cos(dHeading),
43			sinD:          math.Sin(dHeading),
44			identity:      dHeading == 0 && tgt.X == anchorBefore.X && tgt.Y == anchorBefore.Y,
45		}
46	}
47	
48	// apply 计算一帧校正后的位置与朝向：恒等校正原样保留校正前值；否则把校
49	// 正前相对锚点的偏移随锚点一起旋转平移，朝向叠加同一旋转角并归一到
50	// [-π,π)。帧时间与方差不属于几何规则，由调用方处理。
51	//
52	// 朝向按“目标朝向 + 该校正前相对锚点的朝向差”计算，而不是“校正前朝向 +
53	// 旋转角”：二者在数学上（模 2π）等价，但后者先把目标朝向与锚点朝向相减
54	// 再加回，当目标朝向远小于锚点朝向时（例如锚点朝向 1 弧度、目标朝向
55	// 1e-20 弧度），目标朝向会在相减时被锚点朝向的精度吞掉，校正结果退化为
56	// 零——有限且可表示的非零目标朝向必须作为实际定位结果保留。按相对朝向差
57	// 计算时，锚点及原本与锚点朝向完全相同的帧恰好得到目标朝向本身，存在其
58	// 他朝向差的帧仍保留与锚点的相对方向。
59	func (s poseShift) apply(before Pose) (x, y, heading float64) {
60		if s.identity {
61			return before.X, before.Y, before.Heading
62		}
63		dx := before.X - s.anchorX
64		dy := before.Y - s.anchorY
65		return s.x + s.cosD*dx - s.sinD*dy,
66			s.y + s.sinD*dx + s.cosD*dy,
67			normalizeAngle(s.heading + (before.Heading - s.anchorHeading))
68	}
69	
70	// Correct 提交一次已确认回环校正。
71	//
72	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
73	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
74	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
75	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
76	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
77	// 之后至该帧的原运动方差累计值。更早的位姿不变。
78	//
79	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
80	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
81	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
82	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
83	// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
84	// 时间、路标标识与出现编号，而不是误报为距离冲突。
85	//
86	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
87	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
88	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
89	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
90		m.mu.Lock()
91		defer m.mu.Unlock()
92		if m.closed {
93			return CorrectionRecord{}, ErrClosed
94		}
95		st := m.state
96	
97		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
98		// 不做任何校验或状态变更，即使其后又提交过其他校正。
99		if hash, ok := st.corrIndex[req.ID]; ok {
100			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
101				return cloneRecord(st.correctionRecordByID(req.ID)), nil
102			}
103			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
104		}
105	
106		if req.ID == "" {
107			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
108		}
109		tgt := req.Target
110		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
111			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
112		}
113		if tgt.Variance < 0 {
114			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
115		}
116	
117		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
118		anchorIdx := -1
119		for j := 1; j < len(st.trajectory); j++ {
120			if st.trajectory[j].Time == req.Anchor {
121				anchorIdx = j
122				break
123			}
124		}
125		if anchorIdx < 0 {
126			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
127		}
128		end := len(st.trajectory) - 1
129	
130		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
131		for k := anchorIdx - 1; k < len(st.sources); k++ {
132			if st.sources[k] == nil {
133				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
134			}
135		}
136	
137		oldAnchor := st.trajectory[anchorIdx]
138		// 锚点到末帧的整体平移旋转规则（含只调方差的恒等情形）与打开地图时
139		// 的记录几何核对共享同一实现，见上方 poseShift。
140		shift := newPoseShift(tgt, oldAnchor)
141	
142		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
143		next := append([]Pose(nil), st.trajectory...)
144		accumVar := tgt.Variance
145		for j := anchorIdx; j <= end; j++ {
146			old := st.trajectory[j]
147			if j > anchorIdx {
148				accumVar += st.sources[j-1].moveVariance
149			}
150			x, y, heading := shift.apply(old)
151			np := Pose{
152				Time:     old.Time,
153				X:        x,
154				Y:        y,
155				Heading:  heading,
156				Variance: accumVar,
157			}
158			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
159				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
160			}
161			next[j] = np
162		}
163	
164		// 重放器：观测按帧时间归入当时那次出现、旧观测固定贡献作为起点、
165		// 逐条重建位置的规则与打开地图时的核对共享同一实现（见 replay.go）。
166		replay := newObservationReplay(st.config.MergeDistance)
167		for id, lm := range st.landmarks {
168			replay.track(id, lm.occurrenceWindows())
169		}
170		// 重放帧序列：受影响帧（锚点至末帧）用校正后位姿，更早帧用原位姿；
171		// 旧文件帧没有逐帧依据，其观测已计入对应出现的固定旧贡献，这里按
172		// 空观测帧处理。
173		frames := make([]replayFrame, 0, end)
174		for j := 1; j <= end; j++ {
175			var obs []Observation
176			if src := st.sources[j-1]; src != nil {
177				obs = src.observations
178			}
179			frames = append(frames, replayFrame{time: st.trajectory[j].Time, pose: next[j], observations: obs})
180		}
181	
182		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
183		// 回环校正跨越同一路标的多次出现时，各次出现分别聚合、分别遵守合并
184		// 距离限制；已接受观测必然属于某次出现。
185		affected := replay.observed(frames[anchorIdx-1:])
186		affectedKeys := make([]occurrenceKey, 0, len(affected))
187		for k := range affected {
188			affectedKeys = append(affectedKeys, k)
189		}
190		sort.Slice(affectedKeys, func(i, j int) bool {
191			if affectedKeys[i].id != affectedKeys[j].id {
192				return affectedKeys[i].id < affectedKeys[j].id
193			}
194			return affectedKeys[i].num < affectedKeys[j].num
195		})
196	
197		// 逐“出现”登记固定旧贡献：旧文件第 1 次出现的既有观测无法重放，
198		// 其贡献固定为文件中的聚合值（位置不随校正改变）；其余观测随帧序列
199		// 重放。同一路标的不同出现互不参与彼此的合并。
200		for _, k := range affectedKeys {
201			occ := st.landmarks[k.id].appearances[k.num-1]
202			replay.seed(k.id, k.num, occ.legacyCount, occ.legacyMX, occ.legacyMY)
203		}
204		// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
205		// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
206		// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
207		// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
208		// 观测、记录仍有效还是已失效。
209		if rej := replay.replay(frames); rej != nil {
210			switch rej.reason {
211			case replayNonFinite:
212				return CorrectionRecord{}, &RejectError{
213					Kind:          RejectNonFinite,
214					Time:          rej.time,
215					HasTime:       true,
216					Landmark:      rej.id,
217					HasLandmark:   true,
218					Occurrence:    rej.num,
219					HasOccurrence: true,
220				}
221			case replayConflict:
222				return CorrectionRecord{}, &RejectError{
223					Kind:          RejectLandmarkConflict,
224					Time:          rej.time,
225					HasTime:       true,
226					Landmark:      rej.id,
227					HasLandmark:   true,
228					Occurrence:    rej.num,
229					HasOccurrence: true,
230				}
231			default:
232				// 已接受观测必然属于某个已登记出现；归属失败说明内存不变量
233				// 被破坏，不可能由本包产生，按损坏处理而非半提交。
234				return CorrectionRecord{}, ErrCorrupt
235			}
236		}
237		for _, k := range affectedKeys {
238			a := replay.agg(k.id, k.num)
239			occ := st.landmarks[k.id].appearances[k.num-1]
240			if !isFinite(a.x) || !isFinite(a.y) {
241				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
242			}
243			if a.count != occ.count {
244				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
245				return CorrectionRecord{}, ErrCorrupt
246			}
247		}
248	
249		// ---- 组装校正前后快照（记录不可变） ----
250		rec := &CorrectionRecord{
251			ID:        req.ID,
252			Anchor:    req.Anchor,
253			Target:    tgt,
254			EndTime:   st.trajectory[end].Time,
255			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
256			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
257		}
258		for j := anchorIdx; j <= end; j++ {
259			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
260		}
261		for _, k := range affectedKeys {
262			occ := st.landmarks[k.id].appearances[k.num-1]
263			a := replay.agg(k.id, k.num)
264			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
265				ID:         k.id,
266				Occurrence: k.num,
267				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
268				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
269			})
270		}
271	
272		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
273		oldTraj := append([]Pose(nil), st.trajectory...)
274		type occSnapshot struct {
275			key  occurrenceKey
276			occ  *occurrenceState
277			x, y float64
278		}
279		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
280		for _, k := range affectedKeys {
281			occ := st.landmarks[k.id].appearances[k.num-1]
282			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
283		}
284		oldCorrLen := len(st.corrections)
285	
286		st.trajectory = next
287		for _, s := range oldOcc {
288			a := replay.agg(s.key.id, s.key.num)
289			s.occ.x, s.occ.y = a.x, a.y
290		}
291		st.corrections = append(st.corrections, rec)
292		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
293	
294		if err := m.saveReplace(); err != nil {
295			st.trajectory = oldTraj
296			for _, s := range oldOcc {
297				s.occ.x, s.occ.y = s.x, s.y
298			}
299			st.corrections = st.corrections[:oldCorrLen]
300			delete(st.corrIndex, req.ID)
301			return CorrectionRecord{}, err
302		}
303		return cloneRecord(rec), nil
304	}
305	
306	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
307	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
308	func (m *Map) Corrections() ([]CorrectionRecord, error) {
309		m.mu.Lock()
310		defer m.mu.Unlock()
311		if m.closed {
312			return nil, ErrClosed
313		}
314		out := make([]CorrectionRecord, 0, len(m.state.corrections))
315		for _, rec := range m.state.corrections {
316			out = append(out, cloneRecord(rec))
317		}
318		return out, nil
319	}
320	
321	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
322		for _, rec := range st.corrections {
323			if rec.ID == id {
324				return rec
325			}
326		}
327		return nil
328	}
329	
330	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
331		if rec == nil {
332			return CorrectionRecord{}
333		}
334		cp := *rec
335		cp.Poses = append([]PoseChange(nil), rec.Poses...)
336		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
337		return cp
338	}
339

