257						t.Fatalf("kind = %v, want %s", err, c.kind)
258					}
259				}
260			})
261		}
262	
263		// 全部失败后状态仍是 good 段之后：位姿、路标、次数均不变。
264		cur, _ := m.CurrentPose()
265		if cur.Time != 100 {
266			t.Fatalf("current time = %d, state leaked after rejection", cur.Time)
267		}
268		approxEq(t, "variance unchanged", cur.Variance, 0.6)
269		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
270		if len(lms) != 1 || lms[0].ID != "K" || lms[0].Count != 1 {
271			t.Fatalf("landmarks leaked: %v", lms)
