312			t.Fatalf("first record was rewritten: %+v want %+v", recs[0], r1)
313		}
314		// 当前位姿以第二次校正为准。
315		cur, _ := m.CurrentPose()
316		if cur.X != 50 || cur.Y != 60 || cur.Variance != 7 {
317			t.Fatalf("current after second correction = %+v", cur)
