151	func cloneInvalidationResult(r InvalidationResult) InvalidationResult {
152		lms := make([]InvalidatedLandmark, len(r.Landmarks))
153		copy(lms, r.Landmarks)
154		r.Landmarks = lms
155		return r
156	}
157	
158	// landmarkSetHash 计算一个路标标识集合的确定性指纹，用于同一失效操作
159	// 标识的重复内容判定，与输入次序无关（集合语义）。
