10	// buildCorrectionLandmarksMap 构造一份做过校正的地图：t=100 帧两次观测 L、
11	// t=200 帧观测 L 和 M、t=300 帧无观测；校正 c1 覆盖 t=100..300，路标
12	// 出现列表恰为 {L/1, M/1}（L 在范围内被三帧次/同帧多条观测涉及仍只记
13	// 一条）。
14	func buildCorrectionLandmarksMap(t *testing.T, path string) {
15		t.Helper()
16		m, err := Create(path, baseConfig())
17		if err != nil {
18			t.Fatal(err)
19		}
20		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
21			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}, {ID: "L"}}},
22			{Time: 200, DX: 1, Observations: []Observation{{ID: "L"}, {ID: "M"}}},
23			{Time: 300, DX: 1},
24		}}); err != nil {
25			t.Fatal(err)
26		}
27		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
28			t.Fatal(err)
29		}
30		if err := m.Close(); err != nil {
31			t.Fatal(err)
32		}
33	}
34	
35	// 未篡改的文件正常打开，路标列表与提交顺序、内容保持不变。
36	func TestOpenCorrectionLandmarkListAccepted(t *testing.T) {
37		path := filepath.Join(t.TempDir(), "m.pose")
38		buildCorrectionLandmarksMap(t, path)
39		m, err := Open(path)
40		if err != nil {
41			t.Fatalf("open: %v", err)
42		}
43		defer m.Close()
44		recs, err := m.Corrections()
45		if err != nil {
46			t.Fatal(err)
47		}
48		if len(recs) != 1 {
49			t.Fatalf("records = %+v", recs)
50		}
51		lms := recs[0].Landmarks
52		if len(lms) != 2 || lms[0].ID != "L" || lms[0].Occurrence != 1 ||
53			lms[1].ID != "M" || lms[1].Occurrence != 1 {
54			t.Fatalf("landmark changes = %+v", lms)
55		}
56	}
57	
58	// 即使长度与校验和都有效，路标列表少记、多记、重复或错指出现编号，Open
59	// 都必须以 ErrCorrupt 拒绝整份文件、不返回可用地图且原文件不变。
60	func TestOpenRejectsBadCorrectionLandmarkList(t *testing.T) {
61		cases := []struct {
62			name string
63			fn   func(fd *fileData)
64		}{
65			{"missing affected occurrence", func(fd *fileData) {
66				// 删掉 L/1：范围内 L 被多次观测却没有记录。
67				fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[1:]
68			}},
69			{"missing other landmark", func(fd *fileData) {
70				// 删掉 M/1。
71				fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[:1]
72			}},
73			{"duplicate occurrence entry", func(fd *fileData) {
74				// L/1 重复写两条（坐标、次数都合法也不行）。
75				lcs := fd.Corrections[0].Landmarks
76				fd.Corrections[0].Landmarks = append([]landmarkChangeJSON{lcs[0]}, lcs...)
77			}},
78			{"unknown landmark id", func(fd *fileData) {
79				lcs := fd.Corrections[0].Landmarks
80				extra := lcs[0]
81				extra.ID = "GHOST"
82				fd.Corrections[0].Landmarks = append(lcs, extra)
83			}},
84			{"nonexistent occurrence number", func(fd *fileData) {
85				// 范围只涉及 L/1：改写成不存在的 L/3。
86				fd.Corrections[0].Landmarks[0].Occurrence = 3
87			}},
88			{"empty list while range has observations", func(fd *fileData) {
89				fd.Corrections[0].Landmarks = nil
90			}},
91		}
92		for _, tc := range cases {
93			t.Run(tc.name, func(t *testing.T) {
94				path := filepath.Join(t.TempDir(), "m.pose")
95				buildCorrectionLandmarksMap(t, path)
96				tamperFile(t, path, tc.fn)
97				assertOpenCorrupt(t, path)
98			})
