100	}
101	
102	// 范围内没有任何路标观测时，空列表合法；同一份记录被写入非空列表必须拒绝。
103	func TestOpenCorrectionEmptyRangeList(t *testing.T) {
104		path := filepath.Join(t.TempDir(), "m.pose")
105		m, err := Create(path, baseConfig())
106		if err != nil {
107			t.Fatal(err)
108		}
