110		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
111			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}}},
112			{Time: 200, DX: 1},
113		}}); err != nil {
114			t.Fatal(err)
115		}
