147	// 校正没有改变某次出现的位置（恒等校正）：范围内有它的观测，列表仍必须
148	// 保留对应记录；删掉仍要拒绝。
149	func TestOpenIdentityCorrectionKeepsObservedOccurrence(t *testing.T) {
