476		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
477			t.Fatal(err)
478		}
479		// occ2：t=300 位姿 (10,0)，L 本地 (0,0) → (10,0)。
480		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
481			{Time: 300, DX: 10, Observations: []Observation{{ID: "L"}}},
482		}}); err != nil {
483			t.Fatal(err)
484		}
485	
486		// 锚点 t=100 平移 +2（朝向不变）：occ1 观测 → (3,0)，occ2 帧位姿
487		// (12,0)、观测 → (12,0)；各次出现内部无冲突。
488		rec, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 2, Y: 0}})
489		if err != nil {
