512			t.Fatalf("occ2 after correction = %+v", h.Appearances[1])
513		}
514		lms := activeLandmarks(t, m)
515		if len(lms) != 1 || lms["L"].X != 12 {
516			t.Fatalf("active landmarks = %v", lms)
517		}
518	
519		// 第二次校正不改写既有记录，且新记录仍区分出现编号。
520		rec2, err := m.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 13, Y: 0}})
521		if err != nil {
522			t.Fatal(err)
523		}
524		if len(rec2.Landmarks) != 1 || rec2.Landmarks[0].Occurrence != 2 {
525			t.Fatalf("second record = %+v", rec2.Landmarks)
526		}
527		recs, _ := m.Corrections()
528		if len(recs) != 2 {
529			t.Fatalf("records = %d", len(recs))
530		}
531		if recs[0].Landmarks[0].After.X != 3 {
532			t.Fatalf("first record rewritten: %+v", recs[0].Landmarks[0])
