14	// 实现里的 cloneRecord，避免被测实现退化为浅拷贝时期望值与内部
15	// 状态共享底层切片、被一并改写而失去对照意义。
16	func snapshotRecord(rec CorrectionRecord) CorrectionRecord {
17		cp := rec
18		cp.Poses = append([]PoseChange(nil), rec.Poses...)
19		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
20		return cp
