24	// 标识、锚点、目标、末帧时间，以及每条位姿/路标变化的出现编号与
25	// 校正前后值。若返回值不是独立副本，这些改写会污染地图内部状态。
26	func scrambleRecord(rec *CorrectionRecord) {
27		rec.ID = "tampered"
28		rec.Anchor = -999
29		rec.Target = CorrectionTarget{X: -1, Y: -2, Heading: -3, Variance: -4}
30		rec.EndTime = -1
31		for i := range rec.Poses {
32			rec.Poses[i].Before = Pose{Time: -1, X: -100, Y: -100, Heading: -100, Variance: -100}
33			rec.Poses[i].After = Pose{Time: -2, X: -200, Y: -200, Heading: -200, Variance: -200}
34		}
35		for i := range rec.Landmarks {
36			rec.Landmarks[i].ID = "tampered"
37			rec.Landmarks[i].Occurrence = 999
38			rec.Landmarks[i].Before = Landmark{ID: "tampered", X: -1, Y: -1, Count: -1}
39			rec.Landmarks[i].After = Landmark{ID: "tampered", X: -2, Y: -2, Count: -2}
40		}
41	}
42	
43	// checkRecords 断言查询得到的记录列表与期望内容、次序完全一致。
44	func checkRecords(t *testing.T, got []CorrectionRecord, want ...CorrectionRecord) {
45		t.Helper()
46		if len(got) != len(want) {
47			t.Fatalf("records len = %d, want %d: %v", len(got), len(want), got)
48		}
49		for i := range want {
50			if !recordsEqual(got[i], want[i]) {
51				t.Fatalf("record %d = %+v, want %+v", i, got[i], want[i])
52			}
53		}
54	}
55	
56	func findLandmark(lms []Landmark, id string) (Landmark, bool) {
57		for _, lm := range lms {
58			if lm.ID == id {
59				return lm, true
60			}
61		}
62		return Landmark{}, false
63	}
64	
65	// 成功校正同时包含多帧位姿变化与路标变化：改写返回记录后，再次查询
66	// 仍取得原始记录，当前位姿、历史位姿、路标位置与观测次数都保持成功
67	// 校正后的真实结果。
68	func TestCorrectionReturnedRecordIsolated(t *testing.T) {
69		m := newMap(t, baseConfig())
70		if _, err := m.ImportSegment(corrSegment()); err != nil {
71			t.Fatal(err)
72		}
73		req := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
74		rec, err := m.Correct(req)
75		if err != nil {
76			t.Fatalf("Correct: %v", err)
77		}
78		if len(rec.Poses) != 2 || len(rec.Landmarks) != 2 {
79			t.Fatalf("record should cover 2 poses and 2 landmarks: %+v", rec)
80		}
81		want := snapshotRecord(rec)
82	
83		// 调用方改写标识、目标、时间信息以及位姿和路标的校正前后值。
84		scrambleRecord(&rec)
85	
86		// 再次查询仍取得提交时的原始记录。
87		recs, err := m.Corrections()
88		if err != nil {
89			t.Fatal(err)
90		}
91		checkRecords(t, recs, want)
92	
93		// 当前位姿与相应时间的历史位姿保持真实校正结果。
94		cur, _ := m.CurrentPose()
95		if cur.Time != 200 || cur.X != 12 || cur.Y != 20 || cur.Variance != 2.25 {
96			t.Fatalf("current = %+v, want corrected (12,20) v=2.25", cur)
97		}
98		p, _ := m.PoseAt(100)
99		if p.Time != 100 || p.X != 10 || p.Y != 20 || p.Variance != 2 {
100			t.Fatalf("pose at 100 = %+v, want corrected anchor", p)
101		}
102		p, _ = m.PoseAt(200)
103		if p.Time != 200 || p.X != 12 || p.Y != 20 {
104			t.Fatalf("pose at 200 = %+v, want corrected end pose", p)
105		}
106	
107		// 路标位置与观测次数保持真实校正结果，不采用调用方改写的值。
108		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
109		if len(lms) != 2 {
110			t.Fatalf("landmarks = %v", lms)
111		}
112		l1, ok := findLandmark(lms, "L1")
113		if !ok {
114			t.Fatalf("L1 missing: %v", lms)
115		}
116		approxEq(t, "L1 x", l1.X, 11.5)
117		approxEq(t, "L1 y", l1.Y, 20)
118		if l1.Count != 2 {
119			t.Fatalf("L1 count = %d, want 2", l1.Count)
120		}
121		mm, ok := findLandmark(lms, "M")
122		if !ok {
123			t.Fatalf("M missing: %v", lms)
124		}
125		approxEq(t, "M x", mm.X, 12)
126		approxEq(t, "M y", mm.Y, 21)
127		if mm.Count != 1 {
128			t.Fatalf("M count = %d, want 1", mm.Count)
129		}
130	}
131	
132	// 校正跨越同一路标的两次出现（旧出现已失效、新出现仍有效）：改写
133	// 返回记录中的出现编号与各次前后值后，地图中两次出现的位置、计数
134	// 与失效信息都不受影响，区域查询仍只包含有效出现。
135	func TestCorrectionRecordIsolationAcrossOccurrences(t *testing.T) {
136		m := newMap(t, baseConfig())
137		// 全部沿世界 X 轴、朝向 0：初始位姿 (1,2)。
138		// 第 1 次出现：t=100 观测 → (1,2)，t=200 观测 → (2,2)，均值 (1.5,2) 计数 2。
139		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
140			{Time: 100, DX: 0, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
141			{Time: 200, DX: 1, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
142		}}); err != nil {
143			t.Fatal(err)
144		}
145		inv, err := m.Invalidate(Invalidation{ID: "inv1", Reason: "stale", Landmarks: []string{"D"}})
146		if err != nil {
147			t.Fatalf("Invalidate: %v", err)
148		}
149		if inv.Time != 200 || len(inv.Landmarks) != 1 || inv.Landmarks[0].Occurrence != 1 {
150			t.Fatalf("invalidation result = %+v", inv)
151		}
152		// 第 2 次出现：t=300 观测 → (3,2)，t=400 观测 → (4,2)，均值 (3.5,2) 计数 2。
153		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
154			{Time: 300, DX: 1, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
155			{Time: 400, DX: 1, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
156		}}); err != nil {
157			t.Fatal(err)
158		}
159	
160		// 整体平移 +10：两次出现分别重放为 (11.5,2) 与 (13.5,2)，计数不变。
161		rec, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 11, Y: 2, Heading: 0, Variance: 1}})
162		if err != nil {
163			t.Fatalf("Correct: %v", err)
164		}
165		if len(rec.Poses) != 4 || len(rec.Landmarks) != 2 {
166			t.Fatalf("record should cover 4 poses and 2 occurrences: %+v", rec)
167		}
168		if rec.Landmarks[0].Occurrence != 1 || rec.Landmarks[1].Occurrence != 2 ||
169			rec.Landmarks[0].ID != "D" || rec.Landmarks[1].ID != "D" {
170			t.Fatalf("occurrence order = %+v", rec.Landmarks)
171		}
172		want := snapshotRecord(rec)
173	
174		// 调用方改写两次出现的编号与各次前后值。
175		scrambleRecord(&rec)
176	
177		// 再次查询仍取得原始记录（出现编号 1、2 与真实前后值）。
178		recs, err := m.Corrections()
179		if err != nil {
180			t.Fatal(err)
181		}
182		checkRecords(t, recs, want)
183	
184		// 地图中两次出现的位置、计数与失效信息都不受影响。
185		h, err := m.LandmarkAppearances("D")
186		if err != nil {
187			t.Fatal(err)
188		}
189		if len(h.Appearances) != 2 {
190			t.Fatalf("appearances = %+v", h.Appearances)
191		}
192		ap1 := h.Appearances[0]
193		if ap1.Number != 1 || ap1.Active || ap1.Landmark.Count != 2 {
194			t.Fatalf("appearance 1 = %+v", ap1)
195		}
196		approxEq(t, "occ1 x", ap1.Landmark.X, 11.5)
197		approxEq(t, "occ1 y", ap1.Landmark.Y, 2)
198		if ap1.InvalidTime != 200 || ap1.InvalidReason != "stale" || ap1.InvalidOpID != "inv1" {
199			t.Fatalf("appearance 1 invalidation info = %+v", ap1)
200		}
201		ap2 := h.Appearances[1]
202		if ap2.Number != 2 || !ap2.Active || ap2.Landmark.Count != 2 {
203			t.Fatalf("appearance 2 = %+v", ap2)
204		}
205		approxEq(t, "occ2 x", ap2.Landmark.X, 13.5)
206		approxEq(t, "occ2 y", ap2.Landmark.Y, 2)
207	
208		// 区域查询仍只包含有效出现。
209		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
210		if len(lms) != 1 || lms[0].ID != "D" {
211			t.Fatalf("rect query = %v, want only active occurrence", lms)
212		}
213		approxEq(t, "active x", lms[0].X, 13.5)
214		if lms[0].Count != 2 {
215			t.Fatalf("active count = %d, want 2", lms[0].Count)
216		}
217	
218		// 位姿同样保持真实校正结果。
219		cur, _ := m.CurrentPose()
220		if cur.Time != 400 || cur.X != 14 || cur.Y != 2 {
221			t.Fatalf("current = %+v, want corrected (14,2)", cur)
222		}
223	}
224	
225	// Corrections 返回的列表同样是独立副本：改写其中记录、调换或替换
226	// 条目都不影响再次查询的内容与次序；先后取得的两份结果互不影响。
227	// 随后提交覆盖部分轨迹的新校正时，先前取得的结果保留获取时的内容，
228	// 保存的第一条记录仍说明第一次操作，新记录反映第二次操作实际发生
229	// 时的状态。
230	func TestCorrectionsListIsolation(t *testing.T) {
231		m := newMap(t, baseConfig())
232		if _, err := m.ImportSegment(corrSegment()); err != nil {
233			t.Fatal(err)
234		}
235		c1 := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
236		r1, err := m.Correct(c1)
237		if err != nil {
238			t.Fatal(err)
239		}
240		// 第二次校正把末帧移到 (11.5,20)：L1 两次观测 (11,20)/(11.5,20)
241		// 距离 0.5 可接受，均值 (11.25,20)；M 移到 (11.5,21)。
242		c2 := Correction{ID: "c2", Anchor: 200, Target: CorrectionTarget{X: 11.5, Y: 20, Heading: 0, Variance: 7}}
243		r2, err := m.Correct(c2)
244		if err != nil {
245			t.Fatal(err)
246		}
247		// 测试侧快照作为对照，与被测实现的拷贝行为无关。
248		s1, s2 := snapshotRecord(r1), snapshotRecord(r2)
249	
250		listA, err := m.Corrections()
251		if err != nil {
252			t.Fatal(err)
253		}
254		checkRecords(t, listA, s1, s2)
255	
256		// 调用方改写列表中某条记录及其位姿、路标变化，并调换、替换条目。
257		scrambleRecord(&listA[0])
258		listA[0], listA[1] = listA[1], listA[0]
259		listA[1] = CorrectionRecord{ID: "fake"}
260	
261		// 再次查询仍保留提交时的内容与先后次序。
262		listB, err := m.Corrections()
263		if err != nil {
264			t.Fatal(err)
265		}
266		checkRecords(t, listB, s1, s2)
267	
268		// 先后取得的两份结果互不干扰：改写 listB 不污染后续查询。
269		scrambleRecord(&listB[0])
270		listC, err := m.Corrections()
271		if err != nil {
272			t.Fatal(err)
273		}
274		checkRecords(t, listC, s1, s2)
275	
276		// 提交第三次校正，覆盖第一次校正涉及的部分轨迹（末帧 t=200）：
277		// 末帧 (11.5,20) → (11,20)，L1 均值 (11,20)，M → (11,21)。
278		c3 := Correction{ID: "c3", Anchor: 200, Target: CorrectionTarget{X: 11, Y: 20, Heading: 0, Variance: 9}}
279		r3, err := m.Correct(c3)
280		if err != nil {
281			t.Fatal(err)
282		}
283		if len(r3.Poses) != 1 || r3.Poses[0].Before.X != 11.5 || r3.Poses[0].After.X != 11 {
284			t.Fatalf("third record = %+v, want before from c2 result", r3)
285		}
286		s3 := snapshotRecord(r3)
287	
288		// 先前取得的 listC 保留获取时的内容（仍只有两条记录）。
289		checkRecords(t, listC, s1, s2)
290	
291		// 保存的第一条记录仍说明第一次操作的前后变化，新记录反映第三次
292		// 操作实际发生时的变化。
293		listD, err := m.Corrections()
294		if err != nil {
295			t.Fatal(err)
296		}
297		checkRecords(t, listD, s1, s2, s3)
298	}
299	
300	// 同一标识、同一原始请求再次提交：即使地图已接受后续校正，仍返回
301	// 首次记录而非最新轨迹，也不再增加记录；该返回结果同样可被调用方
302	// 独立改写而不污染之后查询或再次取得的首次结果。
303	func TestCorrectionDuplicateResultIsolation(t *testing.T) {
304		m := newMap(t, baseConfig())
305		if _, err := m.ImportSegment(corrSegment()); err != nil {
306			t.Fatal(err)
307		}
308		c1 := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
309		r1, err := m.Correct(c1)
310		if err != nil {
311			t.Fatal(err)
312		}
313		s1 := snapshotRecord(r1)
314		// 地图接受后续校正，轨迹已不同于第一次校正后的状态。
315		c2 := Correction{ID: "c2", Anchor: 200, Target: CorrectionTarget{X: 11.5, Y: 20, Heading: 0, Variance: 7}}
316		if _, err := m.Correct(c2); err != nil {
317			t.Fatal(err)
318		}
319	
320		// 重复提交返回首次记录，不改为返回最新轨迹，也不增加记录。
321		dup, err := m.Correct(c1)
322		if err != nil {
323			t.Fatalf("duplicate correction: %v", err)
324		}
325		if !recordsEqual(dup, s1) {
326			t.Fatalf("duplicate returned %+v, want first record %+v", dup, s1)
327		}
328		recs, _ := m.Corrections()
329		if len(recs) != 2 {
330			t.Fatalf("duplicate added a record: %v", recs)
331		}
332	
333		// 改写重复提交返回的结果，不污染之前取得的列表、之后查询与再次
334		// 取得的首次结果。
335		scrambleRecord(&dup)
336		if !recordsEqual(recs[0], s1) {
337			t.Fatalf("earlier query result polluted: %+v", recs[0])
338		}
339		recs, _ = m.Corrections()
340		if len(recs) != 2 || !recordsEqual(recs[0], s1) {
341			t.Fatalf("saved records polluted by scrambling duplicate result: %v", recs)
342		}
343		dup2, err := m.Correct(c1)
344		if err != nil {
345			t.Fatalf("second duplicate: %v", err)
346		}
347		if !recordsEqual(dup2, s1) {
348			t.Fatalf("second duplicate returned %+v, want first record", dup2)
349		}
350		if recs, _ := m.Corrections(); len(recs) != 2 {
351			t.Fatalf("second duplicate added a record: %v", recs)
352		}
353	}
354	
355	// 没有路标观测的合法校正同样保留位姿记录的隔离行为。
356	func TestCorrectionRecordIsolationNoLandmarks(t *testing.T) {
357		m := newMap(t, baseConfig())
358		// 无观测轨迹：p1 (2,2) v=0.6，p2 (3,2) v=0.7。
359		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
360			{Time: 100, DX: 1, MoveVariance: 0.1},
361			{Time: 200, DX: 1, MoveVariance: 0.1},
362		}}); err != nil {
363			t.Fatal(err)
364		}
365		rec, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 5, Heading: 0, Variance: 1}})
366		if err != nil {
367			t.Fatal(err)
368		}
369		if len(rec.Poses) != 2 || len(rec.Landmarks) != 0 {
370			t.Fatalf("record = %+v, want 2 pose changes and no landmark changes", rec)
371		}
372		want := snapshotRecord(rec)
373	
374		scrambleRecord(&rec)
375	
376		recs, err := m.Corrections()
377		if err != nil {
378			t.Fatal(err)
379		}
380		checkRecords(t, recs, want)
381	
382		cur, _ := m.CurrentPose()
383		if cur.Time != 200 || cur.X != 11 || cur.Y != 5 || cur.Variance != 1.1 {
384			t.Fatalf("current = %+v, want corrected (11,5) v=1.1", cur)
385		}
386		p, _ := m.PoseAt(100)
387		if p.X != 10 || p.Y != 5 || p.Variance != 1 {
388			t.Fatalf("pose at 100 = %+v, want corrected anchor", p)
389		}
390	}
